/** A colour as three numbers from 0 to 1, for pdf-lib's rgb(). */
export const rgb01 = (hex: string): [number, number, number] => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255) as [number, number, number];

